#pragma once
#include <format>
#include <source_location>
#include <string>
#include <string_view>
#include <fstream>
#include <mutex>
#include <iostream>
#include <filesystem>
#include <vector>
#include <memory>
#include <unordered_map>
#include <chrono>

// Disclaimer: Significant portions of this library are generated by Gemini Flash 3.8
// (I based the previous implementation off AixLog and it was a disaster)
// 
// Code here has been reviewed extensively and commented by WildW.
// 
// Simple Logger inspired by BepInEx
namespace Log {
    enum class Severity { Trace, Info, Warning, Error, Fatal };

    constexpr std::string_view to_string(Severity severity) noexcept {
        switch (severity) {
        case Severity::Trace:   return "Trace";
        case Severity::Info:    return "Info";
        case Severity::Warning: return "Warn";
        case Severity::Error:   return "Error";
        case Severity::Fatal:   return "Fatal";
        default:                return "Unknown";
        }
    }

    // Shared file cache: guarantees multiple loggers sharing a filename share the same stream
    inline std::filesystem::path g_logDirectory;
    inline std::unordered_map<std::string, std::shared_ptr<std::ofstream>> g_openFiles;
    inline std::mutex g_globalMutex;

    inline void Init(std::filesystem::path logDir) {
        std::lock_guard lock(g_globalMutex);
        g_logDirectory = std::move(logDir);
    }

    inline std::shared_ptr<std::ofstream> GetOrCreateFile(const std::string& filename) {
        std::lock_guard lock(g_globalMutex);
        auto& stream = g_openFiles[filename];
        if (!stream) {
            stream = std::make_shared<std::ofstream>(g_logDirectory / filename, std::ios::app);
        }
        return stream;
    }

    // Template structure to capture source location of logger calls
    template <typename... Args>
    struct LogLocation {
        std::format_string<Args...> fmt;
        std::source_location loc;

        template <typename StringType>
        consteval LogLocation(const StringType& format_str,
            std::source_location loc = std::source_location::current())
            : fmt(format_str), loc(loc) {
        }
    };

    // Can be used to print messages to cout/cerr and write logs to
    // %USERPROFILE%/AppData/Local/Firaxis Games/Sid Meier's Civilization VI/Logs/CE/
    //
    // Usage:
    // ```
    // MyLogger = new Log::Logger("CE", "Community_Extension.log");
    // MyLogger->Info("Hello, {}!", someName);
    // ```
    class Logger {
        std::string m_tag;
        std::vector<std::shared_ptr<std::ofstream>> m_files;
        std::mutex m_mutex;

    public:
        explicit Logger(std::string tag) : m_tag(std::move(tag)) {}

        Logger(std::string tag, const std::string& filename) : m_tag(std::move(tag)) {
            AddFile(filename);
        }

        Logger(std::string tag, const std::vector<std::string>& filenames) : m_tag(std::move(tag)) {
            for (const auto& file : filenames) AddFile(file);
        }

        // Dynamically attach a new log file
        void AddFile(const std::string& filename) {
            std::lock_guard lock(m_mutex);
            m_files.push_back(GetOrCreateFile(filename));
        }

        template <typename... Args> void Trace(std::type_identity_t<LogLocation<Args...>> l, Args&&... a) { log(Severity::Trace, l, std::forward<Args>(a)...); }
        template <typename... Args> void Info(std::type_identity_t<LogLocation<Args...>> l, Args&&... a) { log(Severity::Info, l, std::forward<Args>(a)...); }
        template <typename... Args> void Warn(std::type_identity_t<LogLocation<Args...>> l, Args&&... a) { log(Severity::Warning, l, std::forward<Args>(a)...); }
        template <typename... Args> void Error(std::type_identity_t<LogLocation<Args...>> l, Args&&... a) { log(Severity::Error, l, std::forward<Args>(a)...); }
        template <typename... Args> void Fatal(std::type_identity_t<LogLocation<Args...>> l, Args&&... a) { log(Severity::Fatal, l, std::forward<Args>(a)...); }

    private:
        template <typename... Args>
        void log(Severity severity, LogLocation<Args...> l, Args&&... args) {
            std::string msg = std::format(l.fmt, std::forward<Args>(args)...);

            std::string_view fullPath = l.loc.file_name();
            std::string_view fileName = fullPath.substr(fullPath.find_last_of("\\/") + 1);

            const char* color = "\x1b[37m"; // White
            if (severity == Severity::Error || severity == Severity::Fatal) color = "\x1b[31m"; // Red
            else if (severity == Severity::Warning) color = "\x1b[33m"; // Yellow
            else if (severity == Severity::Trace)   color = "\x1b[90m"; // Gray (bright black)

            std::lock_guard lock(m_mutex);

            // Lock in the logging date and time
            auto now = std::chrono::system_clock::now();
            // Truncate after 3 decimal points in seconds
            auto milliseconds = std::chrono::floor<std::chrono::milliseconds>(now);

            // Print to console with color; <color>[tag] [severity] [file:line] <msg/></color>
            std::cout << std::format("{}[{}] [{}] [{}:{}] {}{}\n",
                color, m_tag, to_string(severity), fileName, l.loc.line(), msg, "\x1b[0m");

            // Write to all assigned files; [YYYY-MM-DD HH:MM:SS.fff] [tag] [severity] [file:line] <msg/>
            for (auto& file : m_files) {
                if (file && file->is_open()) {
                    *file << std::format("[{:%F %T}] [{}] [{}] [{}:{}] {}\n",
                        milliseconds, m_tag, to_string(severity), fileName, l.loc.line(), msg);
                    file->flush();
                }
            }
        }
    };
}